package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import com.petlis.common.security.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions")
@EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyOrderAdoptionPreparationLocalDatabaseTest {
 @Autowired FeatureStore store;
 @Autowired com.fasterxml.jackson.databind.ObjectMapper json;
 @Autowired org.springframework.transaction.PlatformTransactionManager transactions;LegacyHospitalHistoryLocalDatabaseTest f;LegacyOrderAdoptionPreparationService service;long lab;
 @BeforeEach void setup(){f=new LegacyHospitalHistoryLocalDatabaseTest();f.store=store;f.setup();when(f.f.access.current()).thenReturn(new CurrentActor(f.f.actor,Set.of(PlatformRole.ADMIN),Set.of(),Set.of(),new DataScope(true,Set.of(),Set.of(),null)));store.jdbc().update("UPDATE lin_user SET hospital_id=? WHERE id=?",f.f.hospital,f.f.actor);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET SampleStatus=0,CreateSampleId=0,TestFee=0 WHERE ListDiagnosisProjectId=?",f.f.order);f.f.detail(f.f.test,"8.25",0,0);lab=store.insert("INSERT INTO lin_laboratory(name,code,active) VALUES(?,?,1)",f.f.prefix,f.f.prefix);store.jdbc().update("INSERT INTO lin_lab_test(laboratory_id,test_type_id,price,active) VALUES(?,?,8.25,1)",lab,f.f.test);gate(true,true);service=new LegacyOrderAdoptionPreparationService(store,f.f.access,new LegacyOrderAdoptionService(store,f.f.access),mock(ReviewPermission.class));}
 void gate(boolean read,boolean write){store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES('legacy-order-adoption',?,'owned preparation fixture',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status='ACTIVE'",store.encode(Map.of("enabled",read,"writeEnabled",write)),f.f.actor);}
 LegacyOrderAdoptionPreparationService.Command command(){var p=service.preview((int)f.f.order);return new LegacyOrderAdoptionPreparationService.Command(f.f.actor,(int)lab,new BigDecimal("8.25"),(String)p.get("editToken"),"adopt_"+UUID.randomUUID().toString().replace("-",""),true);}
 @Test void previewAndConfirmationUseOriginalPricesAndExplicitIdentityWithoutTouchingDetails(){var p=service.preview((int)f.f.order);assertEquals("8.25",p.get("detailAmount"));assertEquals(true,p.get("ready"));assertEquals(1,((List<?>)p.get("doctors")).size());assertEquals(1,((List<?>)p.get("laboratories")).size());var rows=store.jdbc().queryForList("SELECT * FROM lin_lb_diagnosisdetail WHERE ListDiagnosisProjectId=?",f.f.order);var c=command();service.prepare((int)f.f.order,c);service.prepare((int)f.f.order,c);assertEquals(rows,store.jdbc().queryForList("SELECT * FROM lin_lb_diagnosisdetail WHERE ListDiagnosisProjectId=?",f.f.order));var e=store.one("SELECT user_id,laboratory_id,payable_amount FROM lin_order_extension WHERE order_id=?",f.f.order);assertEquals(f.f.actor,((Number)e.get("user_id")).intValue());assertEquals(lab,((Number)e.get("laboratory_id")).longValue());assertEquals(0,new BigDecimal("8.25").compareTo(new BigDecimal(e.get("payable_amount").toString())));}
 @Test void missingBarcodeAmountMismatchOrExistingBindingCannotSilentlyPrepare(){store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET UserNO='' WHERE ListDiagnosisProjectId=?",f.f.order);assertEquals(false,service.preview((int)f.f.order).get("ready"));assertEquals(409,assertThrows(BusinessException.class,()->service.prepare((int)f.f.order,command())).getCode());store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET UserNO=?,TestFee=7 WHERE ListDiagnosisProjectId=?",f.f.prefix,f.f.order);assertEquals(false,service.preview((int)f.f.order).get("ready"));}
 @Test void staleSnapshotScopeAndWriteGateAreEnforced(){var c=command();store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET TestPrice=9 WHERE ListDiagnosisProjectId=?",f.f.order);assertEquals(409,assertThrows(BusinessException.class,()->service.prepare((int)f.f.order,c)).getCode());gate(true,false);assertEquals(409,assertThrows(BusinessException.class,service::requireWrite).getCode());doThrow(new BusinessException(403,"admin required")).when(f.f.access).requireAdmin();assertEquals(403,assertThrows(BusinessException.class,()->service.preview((int)f.f.order)).getCode());}

 @Test void auditFailureRollsBackDoctorTotalExtensionAndSourceAudit(){var c=command();var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order);var faulty=new FeatureStore(store.jdbc(),json){@Override public long insert(String sql,Object...args){if(sql.startsWith("INSERT INTO lin_audit_record"))throw new BusinessException(409,"owned adoption audit failure");return super.insert(sql,args);}};var broken=new LegacyOrderAdoptionPreparationService(faulty,f.f.access,new LegacyOrderAdoptionService(faulty,f.f.access),mock(ReviewPermission.class));var tx=new org.springframework.transaction.support.TransactionTemplate(transactions);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);var manager=(org.springframework.transaction.support.AbstractPlatformTransactionManager)transactions;boolean previous=manager.isNestedTransactionAllowed();manager.setNestedTransactionAllowed(true);try{assertThrows(BusinessException.class,()->tx.execute(status->broken.prepare((int)f.f.order,c)));}finally{manager.setNestedTransactionAllowed(previous);}assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_order_extension WHERE order_id=?",Integer.class,f.f.order));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_audit_record WHERE resource_type='ORDER' AND resource_id=? AND action IN ('LEGACY_PREPARED_SUBMITTED','LEGACY_ORDER_ADOPTED')",Integer.class,String.valueOf(f.f.order)));service.prepare((int)f.f.order,c);}
 @Test void explicitConfirmationAndExactAmountCannotBeForged(){var c=command();assertEquals(400,assertThrows(BusinessException.class,()->service.prepare((int)f.f.order,new LegacyOrderAdoptionPreparationService.Command(c.doctorId(),c.laboratoryId(),c.confirmedAmount(),c.expectedToken(),c.requestKey(),false))).getCode());assertEquals(409,assertThrows(BusinessException.class,()->service.prepare((int)f.f.order,new LegacyOrderAdoptionPreparationService.Command(c.doctorId(),c.laboratoryId(),new BigDecimal("8.24"),c.expectedToken(),c.requestKey(),true))).getCode());assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_order_extension WHERE order_id=?",Integer.class,f.f.order));}
}
